#define SPNL_EGRESS_DNS_ATTR_DNS_QUESTION_NAME       "dns.question.name"   /* semconv <- raw[64] -> QNAME (length-prefixed labels walked in userspace) */
#define SPNL_EGRESS_DNS_ATTR_PROCESS_EXECUTABLE_NAME "process.executable.name"   /* semconv <- comm[16] (bpf_get_current_comm) */
#define SPNL_EGRESS_DNS_ATTR_SPNL_DNS_LATENCY_NS     "spnl.dns.latency_ns"   /* spinel <- duration_ns */

/* --- typed consumer for channel "dns" ---
 * `on_emit :dns do |ev| ... end` lowers `ev.<prop>` to these accessors, so the
 * property set a Ruby consumer sees is generated from the same table as the
 * record struct. `i` is the record's index in the last drain (the opaque handle
 * Ruby holds); the byte image itself never crosses the FFI boundary.
 *
 * Expanded in exactly one TU: the one that #defines SPNL_REC_CONSUME_IMPL before
 * including this header (src/runtime/otlp/otlp_agent.c). That TU must define the
 * two functions declared below -- the drained-record lookup and each declared
 * derivation -- and a missing one is a link error, not a silent wrong value. */

/* Declared output capacity of each string derivation, in bytes
 * including the NUL, and >= the longest value that derivation can return
 * (the schema table says why). Handed to the impl by the accessor below AND
 * by the runtime's span builder, so `ev.<prop>` and the attribute it feeds
 * are the same function's output at the same width. */
#define SPNL_REC_DERIVED_DNS_QNAME_CAP           256

#ifdef SPNL_REC_CONSUME_IMPL
const spnl_rec_dns_t *spnl_rec_dns_at(int i);
void spnl_dns_qname(const unsigned char *src, char *out, int cap);   /* qname <- raw */

long spnl_rec_dns_pid(int i) {
    const spnl_rec_dns_t *r = spnl_rec_dns_at(i);
    return r ? (long)r->pid : 0;   /* producer tgid (init-ns) */
}
const char *spnl_rec_dns_comm(int i) {
    const spnl_rec_dns_t *r = spnl_rec_dns_at(i);
    return r ? r->comm : "";   /* bpf_get_current_comm -> process.executable.name */
}
long spnl_rec_dns_cgid(int i) {
    const spnl_rec_dns_t *r = spnl_rec_dns_at(i);
    return r ? (long)r->cgid : 0;   /* cgroup id -> k8s.* pod attribution */
}
long spnl_rec_dns_duration_ns(int i) {
    const spnl_rec_dns_t *r = spnl_rec_dns_at(i);
    return r ? (long)r->duration_ns : 0;   /* resolution RTT; 0 = query-only */
}
const char *spnl_rec_dns_qname(int i) {
    const spnl_rec_dns_t *r = spnl_rec_dns_at(i);
    static char buf[SPNL_REC_DERIVED_DNS_QNAME_CAP];
    if (!r) return "";
    spnl_dns_qname(r->raw, buf, (int)sizeof buf);   /* derived: qname */
    return buf;
}
#endif /* SPNL_REC_CONSUME_IMPL */

