/* Decode one ringbuf record into the mirror. Returns 0, or -1 when the
 * record is shorter than the contract (producer older than this header). */
static inline int spnl_rec_conn_unpack(const void *data, size_t size, spnl_rec_conn_t *out) {
    const unsigned char *p = (const unsigned char *)data;
    if (!data || !out || size < (size_t)SPNL_REC_CONN_MIN) return -1;
    memcpy(&out->hdr, p + SPNL_REC_CONN_OFF_HDR, sizeof out->hdr);
    memcpy(&out->pid, p + SPNL_REC_CONN_OFF_PID, sizeof out->pid);
    memcpy(out->comm, p + SPNL_REC_CONN_OFF_COMM, sizeof out->comm);
    out->comm[sizeof out->comm - 1] = '\0';   /* char[] = C string */
    memcpy(&out->daddr, p + SPNL_REC_CONN_OFF_DADDR, sizeof out->daddr);
    memcpy(&out->dport, p + SPNL_REC_CONN_OFF_DPORT, sizeof out->dport);
    memcpy(&out->family, p + SPNL_REC_CONN_OFF_FAMILY, sizeof out->family);
    memcpy(&out->srtt_us, p + SPNL_REC_CONN_OFF_SRTT_US, sizeof out->srtt_us);
    memcpy(&out->cgid, p + SPNL_REC_CONN_OFF_CGID, sizeof out->cgid);
    memcpy(&out->oldstate, p + SPNL_REC_CONN_OFF_OLDSTATE, sizeof out->oldstate);
    memcpy(&out->daddr6_hi, p + SPNL_REC_CONN_OFF_DADDR6_HI, sizeof out->daddr6_hi);
    memcpy(&out->daddr6_lo, p + SPNL_REC_CONN_OFF_DADDR6_LO, sizeof out->daddr6_lo);
    return 0;
}

