    unsigned char resp[16];                  /* @124  first 16B of the response; "HTTP/1.1 NNN" status parsed in userspace */
    uint64_t cgid;                           /* @144  cgroup id -> k8s.* pod attribution */
    uint64_t start_ktime;                    /* @152  real window start (span anchor + child correlation); 0 on a pre- producer. Not exposed: a raw ktime is an anchor for span assembly (layer 2), not something a consumer can judge on */
    unsigned char hdr_ext[128];              /* @160  first 128B of the request head, scanned for a W3C traceparent in userspace; zero on a pre- producer. Not exposed: raw header bytes, like dns `raw` -- what a consumer wants from them (the trace context) is layer 2's, and the request line is already ev.method / ev.path */
